import datasets
import pandas as pd
import numpy as np
from scipy.optimize import curve_fit
from sklearn.metrics import r2_score
import warnings
warnings.filterwarnings('ignore')

ds = datasets.load_from_disk('/app/data')
df = ds.to_pandas()
groups = df['group'].unique()

def sigmoid(x, a, b, c, d):
    return a / (1 + np.exp(-c * (x - d))) + b

def exp_decay(x, a, b, c):
    return a + b * np.exp(-c * x)

def power_law_asymp(x, a, b, c):
    return a + b * np.power(x, c)

scores = {'sigmoid': [], 'exp_decay': [], 'power_law_asymp': []}

for g in groups:
    data = df[df['group'] == g].dropna()
    x_flops = data['flops'].values
    x_log = data['log_flops'].values
    y = data['brier_score'].values

    # Sigmoid on log_flops
    try:
        p0 = [np.max(y)-np.min(y), np.min(y), 1.0, np.mean(x_log)]
        popt, _ = curve_fit(sigmoid, x_log, y, p0=p0, maxfev=10000)
        y_pred = sigmoid(x_log, *popt)
        scores['sigmoid'].append(r2_score(y, y_pred))
    except:
        pass

    # Exp decay on log_flops
    try:
        popt, _ = curve_fit(exp_decay, x_log, y, maxfev=10000)
        y_pred = exp_decay(x_log, *popt)
        scores['exp_decay'].append(r2_score(y, y_pred))
    except:
        pass

    # Power law with asymptote on flops
    try:
        popt, _ = curve_fit(power_law_asymp, x_flops, y, maxfev=10000)
        y_pred = power_law_asymp(x_flops, *popt)
        scores['power_law_asymp'].append(r2_score(y, y_pred))
    except:
        pass

for model, r2s in scores.items():
    if r2s:
        print(f"{model} mean R2: {np.mean(r2s):.4f} (fitted {len(r2s)}/{len(groups)} groups)")
